WITH eligible AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM orders c WHERE c.store_id = s.id AND c.status <> 'RETURNED')), base AS (SELECT id, store_name, region, opened_date, sqft, REGEXP_REPLACE(store_name, ' ', '') store_name_slug, COALESCE(region, 'UNKNOWN') resolved_region FROM eligible WHERE opened_date >= DATE '2023-02-25' AND region IS NOT NULL), with_latest AS (SELECT s.*, latest.sale_date FROM base s LEFT JOIN LATERAL (SELECT c.sale_date FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) latest ON TRUE), latest AS (SELECT * FROM with_latest QUALIFY RANK() OVER (PARTITION BY region ORDER BY opened_date DESC) = 1), filtered AS (SELECT id, store_name, region, opened_date, sqft, store_name_slug, sale_date, CEIL(sqft) sqft_whole, DATE_FORMAT(opened_date, 'yyyy-MM-dd') opened_date_label FROM latest WHERE region IS NOT NULL) SELECT region, DATE_TRUNC('QUARTER', sale_date) AS quarter_start, CASE WHEN sqft >= 12621 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, AVG(sqft) AS avg_sqft, COUNT_IF(region = 'West') AS west_events FROM filtered GROUP BY 1, 2, 3
